"use strict";
/**
 * Bundler regression — reachability, disk reconciliation, and honest status.
 *
 * `bundle_skill.py` discovers what to copy by walking a skill's own files and
 * following references to a fixed point. The loop itself has been correct since
 * the bundler's first commit. What was wrong is *reachability into it*: a copy
 * already sitting in `<skill>/references/` that the walk no longer reaches was
 * never opened, compared or refreshed — and the bundler then printed `in sync`.
 *
 * Measured on this repo before the fix: 858 bundled files, 749 regenerated by a
 * clean run, 109 never regenerated. Of those, 26 had a `shared/resources/`
 * source and 8 were provably stale — including two copies of a pipeline contract
 * carrying `"current_step": 1`, the exact value the shared source's own warning
 * block exists to forbid. Zero of the 749 *discovered* files were stale, so the
 * bundler was correct on everything it examined and silent about everything else.
 *
 * Two causes, and one tempting fix that had to be rejected:
 *   1. `.json` was absent from REFS_REF_RE's suffix alternation, so a skill whose
 *      only reference was `references/x.json` computed |needed| == 0, took the
 *      early return, and never touched its references/ dir at all.
 *   2. Most of them are reachable by no rule at all — something placed the copy
 *      and nothing points at it any more. Pass 2 therefore reconciles against
 *      DISK: a copy is refreshed because it exists and has a source, not because
 *      discovery found it.
 *
 * REJECTED: following `references/X` out of shared text. It looks like the obvious
 * fix and it over-vendors — `tracker-card-summary.md` names `references/jira-sync.js`
 * while explicitly avoiding the `shared/resources/` form so the bundler will NOT
 * vendor a Jira client into GitHub-only skills. Trying it added 38 unwanted files.
 * A prose mention is not a dependency; the guard test below pins that.
 *
 * Reconciliation writes files discovery never reached, so it needs a safety gate:
 * `writable_copy` refuses anything not demonstrably bundler output, which is what
 * stops an authored file sharing a name with a shared resource from being silently
 * overwritten. Several tests below exist only to pin that gate.
 *
 * Each test builds a throwaway repo and runs the real bundler, so the assertions
 * are about observed behaviour rather than a re-implementation of its regexes.
 *
 * Run: node --test tests/bundle-transitive.test.js
 */

const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");
const test = require("node:test");
const assert = require("node:assert/strict");

const REPO_ROOT = path.resolve(__dirname, "..");
const BUNDLER = path.join(
  REPO_ROOT,
  "skills",
  "create-skill",
  "scripts",
  "bundle_skill.py",
);

const SKILL_MD_HEAD = `---
name: fixture-skill
description: Fixture skill used by the bundler reachability regression test.
---

# Fixture Skill
`;

/** The provenance banner the bundler injects — what marks a file as its output. */
const BANNER = (name) =>
  `<!-- AUTO-GENERATED — DO NOT EDIT. Source: shared/resources/${name}. ` +
  `Regenerate via \`npm run bundle\`. -->\n`;

/**
 * Build a disposable repo with one skill plus a shared/resources tree.
 *
 * A real temp repo keeps the test from mutating tracked files: the bundler
 * rewrites sources in place by design. `t` is required and cleanup is registered
 * immediately after mkdtemp — registering it at the end leaked the repo whenever
 * fixture construction threw.
 */
function makeFixture({ skillFiles = {}, sharedFiles = {}, refsFiles = {} }, t) {
  if (!t || typeof t.after !== "function") {
    throw new Error("makeFixture requires the test context `t` for cleanup");
  }
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "bundle-transitive-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));

  fs.mkdirSync(path.join(root, "skills"), { recursive: true });
  fs.mkdirSync(path.join(root, "shared", "resources"), { recursive: true });
  fs.writeFileSync(path.join(root, "package.json"), '{"name":"fixture"}\n');

  const skillDir = path.join(root, "skills", "fixture-skill");
  fs.mkdirSync(skillDir, { recursive: true });

  const writeAll = (base, files) => {
    for (const [rel, content] of Object.entries(files)) {
      const dest = path.join(base, rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, content);
    }
  };
  writeAll(skillDir, skillFiles);
  writeAll(path.join(root, "shared", "resources"), sharedFiles);
  writeAll(path.join(skillDir, "references"), refsFiles);

  /**
   * Run the bundler with arbitrary argv. Returns {status, stdout} rather than
   * throwing — a non-zero exit is the expected result in some tests. A signal
   * kill (status null) or a missing python3 (ENOENT) is rethrown rather than
   * masquerading as a bundler verdict.
   */
  const run = (argv) => {
    try {
      return {
        status: 0,
        stdout: execFileSync("python3", [BUNDLER, ...argv], {
          encoding: "utf-8",
        }),
      };
    } catch (e) {
      if (e.status == null) throw e;
      return { status: e.status, stdout: (e.stdout || "") + (e.stderr || "") };
    }
  };

  return {
    root,
    skillDir,
    run,
    bundle: () =>
      execFileSync("python3", [BUNDLER, skillDir], { encoding: "utf-8" }),
    readRef: (name) =>
      fs.readFileSync(path.join(skillDir, "references", name), "utf-8"),
    refExists: (name) => fs.existsSync(path.join(skillDir, "references", name)),
    readShared: (name) =>
      fs.readFileSync(path.join(root, "shared", "resources", name), "utf-8"),
    writeShared: (name, content) =>
      fs.writeFileSync(path.join(root, "shared", "resources", name), content),
    chmodShared: (name, mode) =>
      fs.chmodSync(path.join(root, "shared", "resources", name), mode),
    chmodRef: (name, mode) =>
      fs.chmodSync(path.join(skillDir, "references", name), mode),
    refMode: (name) =>
      fs.statSync(path.join(skillDir, "references", name)).mode & 0o777,
    symlinkRef: (name, target) => {
      const dest = path.join(skillDir, "references", name);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.symlinkSync(target, dest);
    },
  };
}

// ---------------------------------------------------------------------------
// The defect itself: copies discovery cannot reach.
// ---------------------------------------------------------------------------

test("a copy reachable by no discovery rule is REFRESHED when its source changes", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
      refsFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
    },
    t,
  );

  fx.bundle();
  fx.writeShared("contract.md", "# Contract\n\nCORRECTED body.\n");
  const stdout = fx.bundle();

  assert.match(
    fx.readRef("contract.md"),
    /CORRECTED body/,
    "This is the defect in full: the source moved on and the bundled copy did " +
      "not, so the copy describes an earlier version forever while the bundler " +
      `reports success. Bundler said:\n${stdout}`,
  );
});

test("`in sync` is not printed when a source-backed copy was actually refreshed", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "contract.md": "# Contract\n\nCURRENT body.\n" },
      refsFiles: {
        "contract.md": `${BANNER("contract.md")}# Contract\n\nSTALE body.\n`,
      },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.doesNotMatch(
    stdout,
    /in sync/,
    `A run that rewrote a stale file must not report it as already correct. Said:\n${stdout}`,
  );
  assert.match(stdout, /reconciled/, "the refresh should be reported");
});

test("`references/x.json` is discovered — .json must be in the suffix alternation", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nThe graph lives in \`references/graph.json\`.\n`,
      },
      sharedFiles: { "graph.json": '{\n  "fixture-skill": []\n}\n' },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.ok(
    fx.refExists("graph.json"),
    "A skill whose only reference is `references/graph.json` must still bundle " +
      "it. Without `json` in the suffix alternation the skill computes " +
      `|needed| == 0 and never touches references/. Said:\n${stdout}`,
  );
});

test("a stale copy WITH a shared source is reconciled even when discovery cannot reach it", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "orphan.md": "# Orphan\n\nCURRENT source body.\n" },
      refsFiles: {
        "orphan.md": `${BANNER("orphan.md")}# Orphan\n\nANCIENT stale body.\n`,
      },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.match(
    fx.readRef("orphan.md"),
    /CURRENT source body/,
    "A file in references/ with a shared/resources/ counterpart is a stale copy, " +
      `whatever discovery thinks. Said:\n${stdout}`,
  );
});

test("the bundler stays idempotent — a second run reports no changes", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/outer.md.\n`,
      },
      sharedFiles: { "outer.md": "# Outer\n\nBody.\n" },
    },
    t,
  );

  fx.bundle();
  const second = fx.bundle();

  assert.match(
    second,
    /in sync/,
    "Idempotence is a load-bearing contract — AGENTS.md, the module docstring and " +
      `the validate.yml freshness step all depend on it. Said:\n${second}`,
  );
});

// ---------------------------------------------------------------------------
// The rejected alternative, pinned so it is not retried.
// ---------------------------------------------------------------------------

test("a `references/X` mention inside shared PROSE does not vendor the file", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/spec.md.\n`,
      },
      sharedFiles: {
        "spec.md":
          "# Spec\n\nHelpers live in the shared library (vendored as " +
          "`references/heavy-client.js` in skills that need it). Its path is " +
          "deliberately not spelled out.\n",
        "heavy-client.js": "module.exports = {};\n",
      },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.refExists("heavy-client.js"),
    false,
    "A prose mention is not a dependency. Vendoring on the strength of one puts " +
      "a Jira client into every GitHub-only skill that merely documents the " +
      "contract — 38 unwanted files when this was tried.",
  );
});

// ---------------------------------------------------------------------------
// The write gate. Reconciliation writes files discovery never reached, so "may
// we write this?" must be answered separately from "is it ours to care about?".
// ---------------------------------------------------------------------------

test("a copy WITHOUT a shared source is left untouched — the out-of-scope boundary", (t) => {
  const NATIVE =
    "# Skill-native\n\nThis file has no shared/resources source.\n";
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing shared.\n` },
      sharedFiles: {},
      refsFiles: { "skill-native.md": NATIVE },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("skill-native.md"),
    NATIVE,
    "83 of this repo's 109 non-regenerated bundled files are skill-native and " +
      "legitimately live in references/. Reconciliation must key on HAVING a " +
      "source, never on mere presence.",
  );
});

for (const [label, skillBody] of [
  ["names it as references/X", "Use `references/guard.md`.\n"],
  ["names it as shared/resources/X", "See shared/resources/guard.md.\n"],
  ["names nothing (reconciliation path)", "Nothing.\n"],
]) {
  test(`an authored file survives when SKILL.md ${label}`, (t) => {
    // The gate must hold on EVERY path into a write. It once guarded only the
    // reconciliation path — the one a file reaches when NOTHING mentions it — so
    // the guarantee held precisely where the danger was smallest, and the test
    // asserting it used the one fixture seed that routed to the working branch.
    const AUTHORED = "# Authored\n\nHand-written, not bundler output.\n";
    const fx = makeFixture(
      {
        skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\n${skillBody}` },
        sharedFiles: { "guard.md": "# Shared\n\nShared body.\n" },
        refsFiles: { "guard.md": AUTHORED },
      },
      t,
    );

    fx.bundle();

    assert.equal(
      fx.readRef("guard.md"),
      AUTHORED,
      "Discovery reaching the name is the ORDINARY case; reconciliation is the " +
        "rare one. A gate on only one of them protects the wrong path.",
    );
  });
}

test("a file that merely QUOTES the banner is not treated as bundler output", (t) => {
  const AUTHORED =
    "# Authored guide\n\nBundled files carry AUTO-GENERATED — DO NOT EDIT at the top.\n";
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "guide.md": "# Shared guide\n\nShared content.\n" },
      refsFiles: { "guide.md": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("guide.md"),
    AUTHORED,
    "Quoting the banner is not carrying one — the declared `Source:` path must " +
      "match the file's own location. A document ABOUT the bundler is precisely " +
      "what quotes its banner.",
  );
});

test("a pre-header-injection copy IS still reconciled", (t) => {
  // The banner alone is too strict a discriminator: copies bundled before header
  // injection existed carry none. Three of the eight files this task corrected
  // were exactly that shape, so a banner-only gate would have refused to fix the
  // very files it was written for.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "legacy.md": "# Legacy\n\nOriginal body.\n" },
      refsFiles: { "legacy.md": "# Legacy\n\nOriginal body.\n" }, // no banner
    },
    t,
  );

  fx.bundle(); // identical-to-source ⇒ recognised as output ⇒ gains the banner
  fx.writeShared("legacy.md", "# Legacy\n\nUPDATED body.\n");
  const stdout = fx.bundle();

  assert.match(
    fx.readRef("legacy.md"),
    /UPDATED body/,
    "A banner-less copy byte-identical to the rewritten source is demonstrably " +
      `bundler output and must keep being refreshed. Said:\n${stdout}`,
  );
});

test("a header-less suffix is not auto-accepted as bundler output", (t) => {
  const AUTHORED = "export const x = 1;\n";
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: { "thing.ts": "export const y = 2;\n" },
      refsFiles: { "thing.ts": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("thing.ts"),
    AUTHORED,
    "Accepting every suffix `autogen_header` declines meant '.mdx', '.ts' and " +
      "'.txt' were auto-accepted on a bare name match. This tree already holds " +
      "15 skill-native .mdx files and one .ts.",
  );
});

test("a symlinked reference is not written through", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/linked.md.\n`,
      },
      sharedFiles: { "linked.md": "# Linked\n\nSource body.\n" },
    },
    t,
  );
  const sourceBefore = fx.readShared("linked.md");
  fx.symlinkRef("linked.md", "../../../shared/resources/linked.md");

  fx.bundle();

  assert.equal(
    fx.readShared("linked.md"),
    sourceBefore,
    "write_bytes writes THROUGH a symlink, so a reference linked back at its own " +
      "source would get the AUTO-GENERATED banner injected into " +
      "shared/resources/ itself, permanently.",
  );
});

// ---------------------------------------------------------------------------
// Robustness on the shared write path.
// ---------------------------------------------------------------------------

test("an out-of-tree reference is refused, not written outside references/", (t) => {
  // `name` is an unsanitised regex capture permitting `.` and `/`, so
  // `shared/resources/../../OUTSIDE.md` escaped both refs_dir and the skill: the
  // bundler printed "bundled references/../../OUTSIDE.md" and created
  // <root>/skills/OUTSIDE.md. Overwriting was blocked by the gate; CREATING was not.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/../../OUTSIDE.md.\n`,
      },
      sharedFiles: {},
    },
    t,
  );
  fs.writeFileSync(path.join(fx.root, "OUTSIDE.md"), "# outside\n");

  const stdout = fx.bundle();

  assert.equal(
    fs.existsSync(path.join(fx.root, "skills", "OUTSIDE.md")),
    false,
    `The bundler must never create a file outside the skill's references/. Said:\n${stdout}`,
  );
  assert.match(stdout, /refusing out-of-tree reference/);
});

test("a non-UTF-8 skill file does not crash the run", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee \`shared/resources/ok.md\`.\n`,
      },
      sharedFiles: { "ok.md": "# OK\n" },
    },
    t,
  );
  fs.writeFileSync(
    path.join(fx.skillDir, "legacy.md"),
    Buffer.from([0x23, 0x20, 0xe9, 0xe8, 0x0a]),
  );

  const res = fx.run([fx.skillDir]);

  assert.equal(
    res.status,
    0,
    `A non-UTF-8 file anywhere in a skill aborted the whole 125-skill run with a ` +
      `raw traceback. Output:\n${res.stdout}`,
  );
  assert.doesNotMatch(res.stdout, /Traceback/);
  assert.ok(
    fx.refExists("ok.md"),
    "and it must still bundle the real reference",
  );
});

test("an executable source keeps its bit, and a drifted bit is repaired", (t) => {
  // Keying the mode rule on the '.sh' suffix left a real 0755 '.js' source with
  // 0644 copies in this very repo, unrepairable by the bundler.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/tool.js.\n`,
      },
      sharedFiles: { "tool.js": "#!/usr/bin/env node\nconsole.log(1);\n" },
    },
    t,
  );
  fx.chmodShared("tool.js", 0o755);
  fx.bundle();
  assert.equal(fx.refMode("tool.js"), 0o755, "the bit must be mirrored");

  fx.chmodRef("tool.js", 0o644);
  fx.bundle();
  assert.equal(fx.refMode("tool.js"), 0o755, "and a drifted bit repaired");
});

test("a read-only source does not lock its own bundled copy", (t) => {
  // Mirroring the mode makes a 0444 source self-locking: the copy becomes 0444
  // and the next run dies with PermissionError before it can update it.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee \`shared/resources/ro.md\`.\n`,
      },
      sharedFiles: { "ro.md": "# RO v1\n" },
    },
    t,
  );
  fx.chmodShared("ro.md", 0o444);
  fx.bundle();

  fx.chmodShared("ro.md", 0o644);
  fx.writeShared("ro.md", "# RO v2 CHANGED\n");
  fx.chmodShared("ro.md", 0o444);

  const stdout = fx.bundle();

  assert.match(
    fx.readRef("ro.md"),
    /v2 CHANGED/,
    "The destination is ours to rewrite whatever mode we last stamped on it. " +
      `Said:\n${stdout}`,
  );
});

test("an unknown flag is refused and writes nothing", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/a.md.\n`,
      },
      sharedFiles: { "a.md": "# A\n" },
    },
    t,
  );

  const res = fx.run(["-al", fx.skillDir]);

  assert.equal(
    res.status,
    2,
    `A misspelt flag must be refused, not treated as a skill path. Output:\n${res.stdout}`,
  );
  assert.equal(fx.refExists("a.md"), false, "and nothing may be written");
});
